//! Trie nodes for the persistent vector.
//!
//! The vector is a bit-partitioned trie: every level consumes `BITS` bits of
//! the index, so a node has at most `BRANCHING` children. Nodes are shared
//! between vector versions through `Rc`, so "modifying" a vector only copies
//! the nodes along one root-to-leaf path (path copying).

use std::rc::Rc;

/// Bits of the index consumed per trie level.
pub const BITS: u32 = 5;
/// Maximum number of children (or elements, for a leaf) per node.
pub const BRANCHING: usize = 1 << BITS;
/// Mask selecting the index bits belonging to a single level.
pub const MASK: usize = BRANCHING - 1;

pub enum Node<T> {
    /// Bottom of the trie: up to `BRANCHING` elements.
    Leaf(Vec<T>),
    /// Interior level: up to `BRANCHING` subtrees.
    Inner(Vec<Rc<Node<T>>>),
}

impl<T> Node<T> {
    pub fn empty_inner() -> Rc<Node<T>> {
        Rc::new(Node::Inner(Vec::new()))
    }

    fn children(&self) -> &Vec<Rc<Node<T>>> {
        match self {
            Node::Inner(children) => children,
            Node::Leaf(_) => panic!("immer: expected an inner node, found a leaf"),
        }
    }

    fn elements(&self) -> &Vec<T> {
        match self {
            Node::Leaf(elements) => elements,
            Node::Inner(_) => panic!("immer: expected a leaf, found an inner node"),
        }
    }

    /// The leaf holding index `index`, reached from a root at `shift`.
    pub fn leaf_for(node: &Rc<Node<T>>, shift: u32, index: usize) -> &Vec<T> {
        let mut current = node;
        let mut level = shift;
        while level > 0 {
            let slot = (index >> level) & MASK;
            current = &current.children()[slot];
            level -= BITS;
        }
        current.elements()
    }

    /// A chain of `shift / BITS` inner nodes ending in `leaf`.
    pub fn path_to(shift: u32, leaf: Rc<Node<T>>) -> Rc<Node<T>> {
        let mut node = leaf;
        let mut level = shift;
        while level > 0 {
            node = Rc::new(Node::Inner(vec![node]));
            level -= BITS;
        }
        node
    }

    /// Copy of `node` with `leaf` appended at the trie's rightmost edge.
    ///
    /// `tail_offset` is the index the new leaf's first element will take, which
    /// is what selects the slot at every level. The caller guarantees there is
    /// room below `shift`.
    pub fn push_leaf(
        node: &Rc<Node<T>>,
        shift: u32,
        tail_offset: usize,
        leaf: Rc<Node<T>>,
    ) -> Rc<Node<T>> {
        let slot = (tail_offset >> shift) & MASK;
        let mut children = node.children().clone();

        let child = if shift == BITS {
            // One level above the leaves: the leaf itself goes in this slot.
            leaf
        } else if slot < children.len() {
            // Descend into the existing rightmost subtree.
            Node::push_leaf(&children[slot], shift - BITS, tail_offset, leaf)
        } else {
            // The subtree does not exist yet; grow a fresh path down to it.
            Node::path_to(shift - BITS, leaf)
        };

        if slot < children.len() {
            children[slot] = child;
        } else {
            children.push(child);
        }
        Rc::new(Node::Inner(children))
    }
}

