//! Forward iteration over a [`Vector`](super::vector::Vector).

use super::vector::Vector;

/// Borrowing iterator, yielding elements in index order.
///
/// The trie descent is done once per leaf chunk and the chunk is then walked
/// directly, so a full traversal costs O(n) rather than O(n log n).
pub struct Iter<'a, T> {
    vector: &'a Vector<T>,
    index: usize,
    chunk: &'a [T],
    /// Offset of the next element inside `chunk`.
    offset: usize,
}

impl<'a, T: Clone> Iter<'a, T> {
    pub(super) fn new(vector: &'a Vector<T>) -> Self {
        Iter {
            vector,
            index: 0,
            chunk: &[],
            offset: 0,
        }
    }
}

impl<'a, T: Clone> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        if self.index >= self.vector.size() {
            return None;
        }
        if self.offset >= self.chunk.len() {
            let (_, chunk, offset) = self.vector.leaf_containing(self.index);
            self.chunk = chunk;
            self.offset = offset;
        }
        let value = &self.chunk[self.offset];
        self.offset += 1;
        self.index += 1;
        Some(value)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.vector.size() - self.index;
        (remaining, Some(remaining))
    }
}

impl<'a, T: Clone> ExactSizeIterator for Iter<'a, T> {}

