//! An immutable vector with structural sharing, mirroring `immer::vector`.

use std::fmt;
use std::ops::Index;
use std::rc::Rc;

use super::iter::Iter;
use super::node::{Node, BITS, BRANCHING, MASK};

/// Persistent random-access sequence.
///
/// Every operation returns a new vector and leaves the receiver untouched; the
/// two versions share all the structure they have in common. Elements already
/// pushed live in the trie rooted at `root`, while the most recent (at most
/// `BRANCHING`) elements are kept in `tail` so that `push_back` usually copies
/// only that small buffer.
pub struct Vector<T> {
    size: usize,
    /// Bits of index consumed by the root level; `0` while the trie is flat.
    shift: u32,
    root: Rc<Node<T>>,
    tail: Rc<Vec<T>>,
}

impl<T: Clone> Vector<T> {
    /// The empty vector, equivalent to `immer::vector<T>{}`.
    pub fn new() -> Self {
        Vector {
            size: 0,
            shift: BITS,
            root: Node::empty_inner(),
            tail: Rc::new(Vec::new()),
        }
    }

    pub fn size(&self) -> usize {
        self.size
    }

    pub fn is_empty(&self) -> bool {
        self.size == 0
    }

    /// Index of the first element held in the tail buffer.
    fn tail_offset(&self) -> usize {
        if self.size < BRANCHING {
            0
        } else {
            ((self.size - 1) >> BITS) << BITS
        }
    }

    /// The element at `index`, or `None` when out of bounds.
    pub fn get(&self, index: usize) -> Option<&T> {
        if index >= self.size {
            return None;
        }
        Some(self.leaf_containing(index).0)
    }

    /// The element at `index`, together with the leaf chunk holding it and the
    /// element's offset inside that chunk. Used by the iterator to amortize the
    /// trie descent over a whole chunk.
    pub(super) fn leaf_containing(&self, index: usize) -> (&T, &[T], usize) {
        debug_assert!(index < self.size);
        let offset = index & MASK;
        let chunk: &[T] = if index >= self.tail_offset() {
            &self.tail
        } else {
            Node::leaf_for(&self.root, self.shift, index)
        };
        (&chunk[offset], chunk, offset)
    }

    /// A new vector with `value` appended.
    pub fn push_back(&self, value: T) -> Self {
        // Fast path: the tail still has room, so only the tail is copied.
        if self.size - self.tail_offset() < BRANCHING {
            let mut tail = (*self.tail).clone();
            tail.push(value);
            return Vector {
                size: self.size + 1,
                shift: self.shift,
                root: Rc::clone(&self.root),
                tail: Rc::new(tail),
            };
        }

        // The tail is full: move it into the trie and start a new one.
        let leaf = Rc::new(Node::Leaf((*self.tail).clone()));
        let tail_offset = self.tail_offset();
        let (root, shift) = if self.root_is_full(tail_offset) {
            // No room left under the current root, so add a level on top.
            let sibling = Node::path_to(self.shift, leaf);
            let root = Rc::new(Node::Inner(vec![Rc::clone(&self.root), sibling]));
            (root, self.shift + BITS)
        } else {
            (
                Node::push_leaf(&self.root, self.shift, tail_offset, leaf),
                self.shift,
            )
        };

        Vector {
            size: self.size + 1,
            shift,
            root,
            tail: Rc::new(vec![value]),
        }
    }

    /// Whether the trie rooted at `shift` cannot address one more leaf.
    fn root_is_full(&self, tail_offset: usize) -> bool {
        tail_offset >> BITS >= 1 << self.shift
    }

    pub fn iter(&self) -> Iter<'_, T> {
        Iter::new(self)
    }
}

impl<T: Clone> Default for Vector<T> {
    fn default() -> Self {
        Vector::new()
    }
}

/// Cloning a vector is O(1): the two versions share the whole structure.
impl<T> Clone for Vector<T> {
    fn clone(&self) -> Self {
        Vector {
            size: self.size,
            shift: self.shift,
            root: Rc::clone(&self.root),
            tail: Rc::clone(&self.tail),
        }
    }
}

impl<T: Clone> Index<usize> for Vector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &T {
        match self.get(index) {
            Some(value) => value,
            None => panic!(
                "immer: index {} out of range for vector of size {}",
                index, self.size
            ),
        }
    }
}

impl<'a, T: Clone> IntoIterator for &'a Vector<T> {
    type Item = &'a T;
    type IntoIter = Iter<'a, T>;

    fn into_iter(self) -> Iter<'a, T> {
        self.iter()
    }
}

impl<T: Clone> FromIterator<T> for Vector<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Self {
        iter.into_iter()
            .fold(Vector::new(), |vector, value| vector.push_back(value))
    }
}

impl<T: Clone + PartialEq> PartialEq for Vector<T> {
    fn eq(&self, other: &Self) -> bool {
        self.size == other.size && self.iter().eq(other.iter())
    }
}

impl<T: Clone + fmt::Debug> fmt::Debug for Vector<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_list().entries(self.iter()).finish()
    }
}

