//! `std::stoi`, including its error behaviour.

use super::terminate::uncaught_exception;

/// C's `isspace` in the default locale. Unlike `is_ascii_whitespace`, this also
/// counts the vertical tab, which `strtol` skips.
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | b'\x0c' | b'\r')
}

/// Why a string could not be converted by [`try_stoi`].
#[derive(Debug, PartialEq, Eq)]
pub enum StoiError {
    /// No digits were found — `std::invalid_argument`.
    InvalidArgument,
    /// The value does not fit in an `int` — `std::out_of_range`.
    OutOfRange,
}

/// Parse a decimal `int` the way `std::stoi` does.
///
/// Leading whitespace and an optional sign are accepted, digits are consumed
/// until the first non-digit, and any trailing characters are ignored: `"12abc"`
/// yields `12`, just as in C++.
pub fn try_stoi(text: &str) -> Result<i32, StoiError> {
    let bytes = text.as_bytes();
    let mut position = 0;

    while position < bytes.len() && is_space(bytes[position]) {
        position += 1;
    }

    let negative = match bytes.get(position) {
        Some(b'-') => {
            position += 1;
            true
        }
        Some(b'+') => {
            position += 1;
            false
        }
        _ => false,
    };

    let digits_start = position;
    // Accumulate the magnitude, saturating so that absurdly long inputs are
    // reported as out-of-range instead of wrapping.
    let mut magnitude: i64 = 0;
    while let Some(&byte) = bytes.get(position) {
        if !byte.is_ascii_digit() {
            break;
        }
        magnitude = magnitude
            .saturating_mul(10)
            .saturating_add((byte - b'0') as i64);
        position += 1;
    }

    if position == digits_start {
        return Err(StoiError::InvalidArgument);
    }

    let value = if negative { -magnitude } else { magnitude };
    if value < i32::MIN as i64 || value > i32::MAX as i64 {
        return Err(StoiError::OutOfRange);
    }
    Ok(value as i32)
}

/// `std::stoi`: like [`try_stoi`], but a failure terminates the process with the
/// same stderr output and exit status as the uncaught C++ exception would.
pub fn stoi(text: &str) -> i32 {
    match try_stoi(text) {
        Ok(value) => value,
        Err(StoiError::InvalidArgument) => uncaught_exception("std::invalid_argument", "stoi"),
        Err(StoiError::OutOfRange) => uncaught_exception("std::out_of_range", "stoi"),
    }
}
